public class WildcardAnalyzer {
    public static boolean isImportedByWildcard(String wildcardPkg, String targetFQN) {
        // Example: 'java.util.*' matches 'java.util.List' but NOT 'java.util.concurrent.Future'
        return false;
    }

    public static void main(String[] args) {
        System.out.println(isImportedByWildcard("java.util.*", "java.util.ArrayList"));
        System.out.println(isImportedByWildcard("java.util.*", "java.util.concurrent.Callable"));
    }
}

practiceProblems.solution:
public class WildcardAnalyzer {
    public static boolean isImportedByWildcard(String wildcardPkg, String targetFQN) {
        if (wildcardPkg == null || targetFQN == null) return false;
        if (!wildcardPkg.endsWith(".*")) return false;
        String basePkg = wildcardPkg.substring(0, wildcardPkg.length() - 2);
        int lastDot = targetFQN.lastIndexOf('.');
        if (lastDot == -1) return false;
        String classPkg = targetFQN.substring(0, lastDot);
        return basePkg.equals(classPkg);
    }

    public static void main(String[] args) {
        System.out.println(isImportedByWildcard("java.util.*", "java.util.ArrayList"));
        System.out.println(isImportedByWildcard("java.util.*", "java.util.concurrent.Callable"));
    }
}

