import java.util.*;

public class ImportOrganizer {
    public static List<String> organizeImports(List<String> rawImports) {
        List<String> staticImports = new ArrayList<>();
        List<String> javaImports = new ArrayList<>();
        List<String> otherImports = new ArrayList<>();
        for (String imp : rawImports) {
            if (imp.startsWith("import static")) {
                staticImports.add(imp);
            } else if (imp.startsWith("import java.") || imp.startsWith("import javax.")) {
                javaImports.add(imp);
            } else {
                otherImports.add(imp);
            }
        }
        Collections.sort(staticImports);
        Collections.sort(javaImports);
        Collections.sort(otherImports);
        List<String> result = new ArrayList<>();
        result.addAll(staticImports);
        result.addAll(javaImports);
        result.addAll(otherImports);
        return result;
    }

    public static void main(String[] args) {
        List<String> imports = Arrays.asList(
            "import com.company.util.Helper;",
            "import java.util.List;",
            "import static java.lang.Math.PI;",
            "import static org.junit.Assert.assertEquals;",
            "import java.io.File;"
        );
        for (String imp : organizeImports(imports)) {
            System.out.println(imp);
        }
    }
}

