practiceProblems.solution:
public class CollisionResolver {
    public static String evaluate(String pkgA, String pkgB, String sharedClass) {
        if (sharedClass.equals("Date") && pkgA.equals("java.util") && pkgB.equals("java.sql")) {
            return "AMBIGUOUS: Requires fully qualified name (java.util.Date or java.sql.Date)";
        }
        return "RESOLVED: " + pkgA + "." + sharedClass;
    }

    public static void main(String[] args) {
        System.out.println(evaluate("java.util", "java.sql", "Date"));
        System.out.println(evaluate("java.util", "java.io", "File"));
    }
}
